-- ============================================
-- LUMA — Thème 17 : LONG 2/3 x4 — Une saison complète avec une équipe amateur
-- ============================================


update scenarios set content = '{"characters": {"coach": "l''entraîneur", "teammate": "un coéquipier"}, "start_node": "n1", "nodes": {"n1": {"speaker": "coach", "text": "Season opener today! Nervous, or ready to show what we''ve worked on?", "text_fr": "Ouverture de saison aujourd''hui ! Nerveux, ou prêt à montrer sur quoi on a travaillé ?", "choices": [{"text": "A bit of both, honestly. Let''s go show what we''ve got.", "text_fr": "Un peu des deux, honnêtement. Allons montrer ce qu''on vaut.", "next": "n2"}]}, "n2": {"speaker": "you_thought", "text": "(The first match ends in a disappointing loss, spirits low in the locker room.)", "text_fr": "(Le premier match se termine par une défaite décevante, le moral bas dans les vestiaires.)", "choices": [{"text": "(Encourage the team despite the tough loss.)", "text_fr": "(Encourage l''équipe malgré la dure défaite.)", "next": "n3"}]}, "n3": {"speaker": "teammate", "text": "That was rough. First game jitters, I guess.", "text_fr": "C''était dur. Le trac du premier match, je suppose.", "choices": [{"text": "We''ll bounce back, this is just the start of the season.", "text_fr": "On va rebondir, c''est juste le début de la saison.", "next": "n4"}]}, "n4": {"speaker": "coach", "text": "(Mid-season) Three wins, two losses. We''re finding our rhythm as a team.", "text_fr": "(Mi-saison) Trois victoires, deux défaites. On trouve notre rythme en tant qu''équipe.", "choices": [{"text": "It really feels like we''re clicking more each week.", "text_fr": "Ça se sent vraiment qu''on se synchronise de plus en plus chaque semaine.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(A key injury to your star player threatens to derail the team''s momentum.)", "text_fr": "(Une blessure clé de votre meilleur joueur menace de faire dérailler l''élan de l''équipe.)", "choices": [{"text": "(Step up to fill the gap during the injury.)", "text_fr": "(Prends du galon pour combler le vide pendant la blessure.)", "next": "n6"}, {"text": "(Support the team in adjusting their strategy without that player.)", "text_fr": "(Soutiens l''équipe dans l''ajustement de sa stratégie sans ce joueur.)", "next": "n6"}]}, "n6": {"speaker": "coach", "text": "We need everyone to step up while we''re missing our star. Can you handle more responsibility?", "text_fr": "On a besoin que tout le monde monte en puissance pendant qu''on manque notre star. Tu peux gérer plus de responsabilité ?", "choices": [{"text": "Absolutely, I''m ready to take on a bigger role.", "text_fr": "Absolument, je suis prêt à prendre un rôle plus important.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(Weeks pass, and the team rallies together, winning matches despite the setback.)", "text_fr": "(Des semaines passent, et l''équipe se rassemble, gagnant des matchs malgré le revers.)", "choices": [{"text": "(Feel proud of how the team has adapted together.)", "text_fr": "(Ressens de la fierté de comment l''équipe s''est adaptée ensemble.)", "next": "n8"}]}, "n8": {"speaker": "teammate", "text": "Honestly, this adversity brought us closer as a team, oddly enough.", "text_fr": "Honnêtement, cette adversité nous a rapprochés en tant qu''équipe, étrangement.", "choices": [{"text": "It really did. We''re playing for each other now, not just ourselves.", "text_fr": "C''est vraiment le cas. On joue les uns pour les autres maintenant, pas juste pour nous-mêmes.", "next": "n9"}]}, "n9": {"speaker": "coach", "text": "(Final match approaching) This is it, the championship game. Everything we''ve built comes down to this.", "text_fr": "(Match final approchant) C''est le moment, le match du championnat. Tout ce qu''on a construit se joue là.", "choices": [{"text": "We''re ready, coach. This team has earned this moment.", "text_fr": "On est prêts, coach. Cette équipe a mérité ce moment.", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(The championship match is intense, tied until the final minutes.)", "text_fr": "(Le match du championnat est intense, à égalité jusqu''aux dernières minutes.)", "choices": [{"text": "(Give everything you have in the final push.)", "text_fr": "(Donne tout ce que tu as dans la poussée finale.)", "next": "n11"}]}, "n11": {"speaker": "teammate", "text": "(As the final whistle blows) We won! We actually won the championship!", "text_fr": "(Alors que le coup de sifflet final retentit) On a gagné ! On a vraiment gagné le championnat !", "choices": [{"text": "(Overwhelmed with emotion, embrace your teammates in celebration.)", "text_fr": "(Submergé par l''émotion, prends tes coéquipiers dans tes bras en célébration.)", "next": "n12"}]}, "n12": {"speaker": "coach", "text": "I''m so proud of this team. From that rough first loss to champions — incredible journey.", "text_fr": "Je suis tellement fier de cette équipe. De cette dure première défaite aux champions — un voyage incroyable.", "choices": [{"text": "This season taught me more about teamwork than I ever expected.", "text_fr": "Cette saison m''a appris plus sur le travail d''équipe que je ne l''aurais jamais imaginé.", "next": "end_champions"}]}, "end_champions": {"speaker": "coach", "text": "That''s what a real season is about. Congratulations, champions!", "text_fr": "C''est ça une vraie saison. Félicitations, champions !", "end": true, "ending_label": "Une saison complète, du doute au titre de champion 🏆⚽"}}}'::jsonb, is_playable = true
where title = 'Une saison complète avec une équipe amateur'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
